from collections import deque
def flood(g,val):
    h,w=len(g),len(g[0]); reach=set()
    for i in range(h):
        for j in range(w):
            if g[i][j]==val:
                q=deque([(i,j)]); seen={(i,j)}
                while q:
                    y,x=q.popleft(); reach.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<h and 0<=nx<w and g[ny][nx]==val and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
    return reach
def f(g):
    h,w=len(g),len(g[0])
    L={i for i in range(h) if all(x==g[i][0] for x in g[i])}
    C={j for j in range(w) if all(g[i][j]==g[0][j] for i in range(h))}
    out=[r[:] for r in g]
    # collect line cells
    linecells=set(L)|set((i,j) for i in range(h) for j in C)
    # flood from line cells through same color
    col=g[L.__iter__().__next__() if L else [0]][0] if False else None
    linecol=None
    if L: linecol=g[min(L)][0]
    elif C: linecol=g[0][min(C)]
    if linecol is not None:
        reach=flood(g,linecol)&linecells
        reach|= {(i,j) for i in L for j in range(w)} | {(i,j) for j in C for i in range(h)}
        # plus connected non-line cells of same color
        reach |= flood(g,linecol)
        for i in range(h):
            for j in range(w):
                if (i,j) in reach: out[i][j]=2
    return out
