def runs(g,val):
    h,w=len(g),len(g[0]); res=[]
    for i in range(h):
        j=0
        while j<w:
            if g[i][j]==val:
                k=j
                while k<w and g[i][k]==val: k+=1
                res.append(('h',i,j,k-j)); j=k
            else: j+=1
